-- Dev seed data. Run after 1.ddl.sql and the migrations:
--   psql $DATABASE_URL -f db/seeds/dev.seed.sql
-- UUIDs (events, actions, simulations) are generated by the DB. Because that makes
-- event/action/log rows non-deterministic, the DO block only runs on an empty event table.

SET search_path = fresnel, public;

BEGIN;

------------------------------------------------------------------------------
-- action_type (also seeded by the DDL; kept here so the seed stands alone)
------------------------------------------------------------------------------
INSERT INTO action_type (code, label_he, active) VALUES
  ('official_response', 'הודעת דו"צ',          true),
  ('consultation',      'התייעצות',            true),
  ('reporter_contact',  'תיאום עם כתב',        true),
  ('external_contact',  'פנייה לגורם חיצוני',  true),
  ('field_collection',  'איסוף מידע מהשטח',    true),
  ('source_analysis',   'ניתוח מקורות',        true),
  ('fact_check',        'בדיקת אמינות מידע',   true),
  ('monitor',           'מעקב אחר התפתחות',    true),
  ('other',             'אחר',                 true)
ON CONFLICT (code) DO NOTHING;

------------------------------------------------------------------------------
-- narrative (arena values follow the Arena enum: israel / arab / intl)
------------------------------------------------------------------------------
INSERT INTO narrative
  (narrative_id, title, summary, is_anomaly, arena, detected_at,
   item_list, platforms, shares_count, views_count, languages, is_flagged, received_at)
VALUES
  ('nar-001', 'תמונות מזויפות מהגבול הצפוני',
   'תמונות ישנות מופצות כאילו צולמו הלילה בגבול הצפון',
   true, ARRAY['israel'], now() - interval '3 days',
   ARRAY['item-1001','item-1002','item-1003'], ARRAY['telegram','x'],
   5400, 182000, ARRAY['he','ar'], true, now() - interval '3 days'),
  ('nar-002', 'שמועה על מחסור בדלק',
   'הודעות ברשתות על סגירת תחנות דלק ברחבי הארץ',
   true, ARRAY['israel'], now() - interval '2 days',
   ARRAY['item-2001','item-2002'], ARRAY['facebook','whatsapp'],
   12800, 95000, ARRAY['he'], false, now() - interval '2 days'),
  ('nar-003', 'קמפיין בערבית נגד הסכמי נורמליזציה',
   'רשת חשבונות מתואמת מפיצה מסרים אחידים',
   true, ARRAY['arab'], now() - interval '36 hours',
   ARRAY['item-3001','item-3002','item-3003','item-3004'], ARRAY['x','telegram','tiktok'],
   30200, 740000, ARRAY['ar'], true, now() - interval '36 hours'),
  ('nar-004', 'סרטון מניפולטיבי על פעילות צה"ל בעזה',
   'סרטון ערוך מופץ באנגלית עם כיתוב מטעה',
   true, ARRAY['intl','arab'], now() - interval '1 day',
   ARRAY['item-4001','item-4002'], ARRAY['x','youtube','instagram'],
   8700, 410000, ARRAY['en','ar'], false, now() - interval '1 day'),
  ('nar-005', 'ויכוח ברשת על חוק הגיוס',
   'שיח ציבורי רגיל, ללא סימני פעילות מתואמת',
   false, ARRAY['israel'], now() - interval '12 hours',
   ARRAY['item-5001'], ARRAY['facebook'],
   320, 14000, ARRAY['he'], false, now() - interval '12 hours'),
  ('nar-006', 'תיעוד אירוע ביטחוני בצפון (תרגיל)',
   'נרטיב עבר ששימש לתרגול משתמשים',
   true, ARRAY['israel','arab'], now() - interval '90 days',
   ARRAY['item-6001','item-6002'], ARRAY['telegram'],
   2100, 56000, ARRAY['he','ar'], false, now() - interval '90 days'),
  ('nar-007', 'פוסטים מבוטים על חטופים',
   'חשבונות מזויפים מפיצים מידע כוזב למשפחות',
   true, ARRAY['israel','intl'], now() - interval '6 hours',
   ARRAY['item-7001','item-7002','item-7003'], ARRAY['x','facebook'],
   950, 38000, ARRAY['he','en'], true, now() - interval '6 hours')
ON CONFLICT (narrative_id) DO NOTHING;

------------------------------------------------------------------------------
-- simulated_narrative, event, action, event_log (ids generated by the DB)
------------------------------------------------------------------------------
DO $$
DECLARE
  sim1 uuid := gen_random_uuid();
  sim2 uuid := gen_random_uuid();
  ev1 uuid; ev2 uuid; ev3 uuid; ev4 uuid; ev5 uuid; ev6 uuid;
  ac1 uuid; ac2 uuid; ac3 uuid; ac4 uuid; ac5 uuid; ac6 uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM event) THEN
    RAISE NOTICE 'event table is not empty, skipping event/action/log seed';
    RETURN;
  END IF;

  INSERT INTO simulated_narrative (narrative_id, simulation_id) VALUES
    ('nar-006', sim1),
    ('nar-001', sim1),
    ('nar-006', sim2);

  -- event (one open real event per narrative; simulations may repeat)
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at)
    VALUES ('nar-001', 'high', 'in_progress', false, 'user-alice', now() - interval '3 days')
    RETURNING event_id INTO ev1;
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at,
                     closed_at, closed_by, closure_summary)
    VALUES ('nar-002', 'medium', 'closed', false, 'user-bob', now() - interval '2 days',
            now() - interval '1 day', 'user-bob',
            'השמועה הופרכה והופצה הודעת דו"צ. אין התפתחויות נוספות.')
    RETURNING event_id INTO ev2;
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at)
    VALUES ('nar-003', 'critical', 'open', false, 'user-alice', now() - interval '30 hours')
    RETURNING event_id INTO ev3;
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at)
    VALUES ('nar-004', 'high', 'in_progress', false, 'user-carol', now() - interval '20 hours')
    RETURNING event_id INTO ev4;
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at)
    VALUES ('nar-006', 'medium', 'in_progress', true, 'system', now() - interval '5 hours')
    RETURNING event_id INTO ev5;
  INSERT INTO event (narrative_id, severity, status, is_simulation, created_by, created_at,
                     closed_at, closed_by, closure_summary)
    VALUES ('nar-006', 'low', 'closed', true, 'system', now() - interval '10 days',
            now() - interval '9 days', 'user-bob', 'תרגיל הושלם בהצלחה.')
    RETURNING event_id INTO ev6;

  -- action
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
    VALUES (ev1, 'source_analysis', 'ניתוח מקור התמונות', 'התמונות מקורן בארכיון 2019',
            'user-alice', now() - interval '70 hours')
    RETURNING action_id INTO ac1;
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
    VALUES (ev1, 'consultation', 'התייעצות עם קצין המבצעים', NULL,
            'user-alice', now() - interval '60 hours')
    RETURNING action_id INTO ac2;
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at,
                      deleted_at, deleted_by)
    VALUES (ev1, 'other', 'רישום שגוי', 'נמחק בטעות', 'user-alice',
            now() - interval '55 hours', now() - interval '54 hours', 'user-alice')
    RETURNING action_id INTO ac3;
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
    VALUES (ev2, 'fact_check', 'בדיקה מול משרד האנרגיה', 'אין מחסור בפועל',
            'user-bob', now() - interval '40 hours')
    RETURNING action_id INTO ac4;
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
    VALUES (ev2, 'official_response', 'פרסום הודעת דו"צ מפריכה', NULL,
            'user-bob', now() - interval '30 hours')
    RETURNING action_id INTO ac5;
  INSERT INTO action (event_id, action_type, title, description, performed_by, performed_at)
    VALUES (ev4, 'reporter_contact', 'תיאום עם כתב בינלאומי', 'נשלח חומר הפרכה',
            'user-carol', now() - interval '10 hours')
    RETURNING action_id INTO ac6;

  -- event_log (append-only)
  INSERT INTO event_log (event_id, action_id, kind, actor_id, from_value, to_value, details, client, at) VALUES
    (ev1, NULL, 'event_created',        'user-alice', NULL,          'open',        '{}', 'web',    now() - interval '3 days'),
    (ev1, ac1,  'action_created',       'user-alice', NULL,          NULL,          '{"title":"ניתוח מקור התמונות"}', 'web', now() - interval '70 hours'),
    (ev1, NULL, 'event_status_changed', 'system',     'open',        'in_progress', '{}', 'system', now() - interval '70 hours'),
    (ev1, ac2,  'action_created',       'user-alice', NULL,          NULL,          '{"title":"התייעצות עם קצין המבצעים"}', 'mobile', now() - interval '60 hours'),
    (ev1, ac3,  'action_created',       'user-alice', NULL,          NULL,          '{"title":"רישום שגוי"}', 'web', now() - interval '55 hours'),
    (ev1, ac3,  'action_deleted',       'user-alice', NULL,          NULL,          '{}', 'web',    now() - interval '54 hours'),
    (ev2, NULL, 'event_created',        'user-bob',   NULL,          'open',        '{}', 'web',    now() - interval '2 days'),
    (ev2, ac4,  'action_created',       'user-bob',   NULL,          NULL,          '{"title":"בדיקה מול משרד האנרגיה"}', 'web', now() - interval '40 hours'),
    (ev2, ac5,  'action_created',       'user-bob',   NULL,          NULL,          '{"title":"פרסום הודעת דו\"צ מפריכה"}', 'web', now() - interval '30 hours'),
    (ev2, NULL, 'event_closed',         'user-bob',   'in_progress', 'closed',      '{}', 'web',    now() - interval '1 day'),
    (ev3, NULL, 'event_created',        'user-alice', NULL,          'open',        '{}', 'mobile', now() - interval '30 hours'),
    (ev4, NULL, 'event_created',        'user-carol', NULL,          'open',        '{}', 'web',    now() - interval '20 hours'),
    (ev4, ac6,  'action_created',       'user-carol', NULL,          NULL,          '{"title":"תיאום עם כתב בינלאומי"}', 'web', now() - interval '10 hours'),
    (ev5, NULL, 'event_created',        'system',     NULL,          'open',        '{"simulation":true}', 'system', now() - interval '5 hours'),
    (ev6, NULL, 'event_created',        'system',     NULL,          'open',        '{"simulation":true}', 'system', now() - interval '10 days'),
    (ev6, NULL, 'event_closed',         'user-bob',   'open',        'closed',      '{}', 'web',    now() - interval '9 days');
END $$;

COMMIT;
